#Requires -Version 5.1
# fix-dashboard-sinasignar.ps1
# 1. Dashboard - datos no actualizados:
#    Boton refresh (icono RefreshCw) junto al titulo de Asignaciones.
#    Al pulsar, recarga todas las asignaciones desde Supabase.
#    Sin el boton, los datos solo se cargaban al entrar a la pagina.
# 2. Dashboard - sin asignar:
#    En la vista de dia, muestra un panel ambar con los RRHH
#    que no tienen ninguna asignacion ese dia.
# 3. Planificador movil - sin asignar:
#    Ampliar el bloque "Sin asignar" para incluir tambien los vehiculos
#    que no estan asignados ese dia (antes solo mostraba personas).

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix dashboard + planificador movil" -ForegroundColor Cyan

Write-Host "  -> src\app\dashboard\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\dashboard\page.tsx"), $bytes)
Write-Host "  OK: 33 KB" -ForegroundColor Green

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 70 KB" -ForegroundColor Green

$dash = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\dashboard\page.tsx"), [System.Text.Encoding]::UTF8)
$plan = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
if ($dash.Contains("RefreshCw"))          { Write-Host "  OK: boton refresh en dashboard" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($dash.Contains("Sin asignar"))        { Write-Host "  OK: sin asignar en dashboard" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($plan.Contains("unassignedVehicles")) { Write-Host "  OK: vehiculos sin asignar en movil" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host '  git add src\app\dashboard\page.tsx src\app\planificacion\page.tsx'
Write-Host '  git commit -m "feat: dashboard refresh + sin asignar + vehiculos sin asignar movil"'
Write-Host '  git push'
